"import React from 'react';
import {
  AbsoluteFill,
  interpolate,
  OffthreadVideo,
  Series,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';

export type BeatItem =
  | {
      kind: 'clip';
      durationInFrames: number;
      videoFile: string;
      topTag: string;
      accentColor: string;
      zoomStart?: number;
      zoomEnd?: number;
      shakeIntro?: boolean;
    }
  | {
      kind: 'broll';
      durationInFrames: number;
      topTag: string;
      monitorTitle: string;
      headline: string;
      lines: string[];
      ctaText?: string;
      accentColor: string;
    };

export interface HybridEpisodeProps {
  episodeLabel: string;
  beats: BeatItem[];
}

const ClipBeat: React.FC<{ beat: Extract<BeatItem, { kind: 'clip' }> }> = ({ beat }) => {
  const frame = useCurrentFrame();
  const z0 = beat.zoomStart ?? 1.0;
  const z1 = beat.zoomEnd ?? 1.09;
  const scale = interpolate(frame, [0, beat.durationInFrames], [z0, z1], {
    extrapolateRight: 'clamp',
  });

  const shakeX =
    beat.shakeIntro && frame < 15
      ? Math.sin(frame * 2.9) * 14 * (1 - frame / 15)
      : 0;
  const shakeY =
    beat.shakeIntro && frame < 15
      ? Math.cos(frame * 3.4) * 10 * (1 - frame / 15)
      : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: '#050814', overflow: 'hidden' }}>
      <AbsoluteFill
        style={{
          transform: `translate(${shakeX}px, ${shakeY}px) scale(${scale})`,
        }}
      >
        <OffthreadVideo
          src={staticFile(`clips/${beat.videoFile}`)}
          muted
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
          }}
        />
      </AbsoluteFill>

      {/* Subtle top vignette for readability without blocking bottom area for Captions */}
      <AbsoluteFill
        style={{
          background:
            'linear-gradient(180deg, rgba(5,8,20,0.68) 0%, rgba(5,8,20,0) 24%, rgba(5,8,20,0
